examples.mysql:
SELECT x, 100.0 / NULLIF(x, 0) AS ratio, COALESCE(100.0 / NULLIF(x, 0), 0) AS ratio_or_zero
FROM (SELECT 0 AS x UNION ALL SELECT 4 UNION ALL SELECT 8) AS t
ORDER BY x;

